// Create an ObjectPool for WtUInt32 (unsigned int) and export it as an opaque handle (void *)
// This avoids template type exposure in the harness object pool while allowing cross-stub reuse via attributes.
ObjectPool<WtUInt32> *pool = new ObjectPool<WtUInt32>();
// Track the pool type and live allocation count to enforce API constraints in other stubs
FUZZ_SET_ATTR_STR(pool, "kind", "ObjectPool<WtUInt32>");
FUZZ_SET_ATTR_INT(pool, "live_count", 0);
// Creating the pool must not allocate any T instances; we only track live_count here
// Validation: live_count starts at 0 and pool is returned for reuse

// Validate that the opaque handle is for the correct pool type
const char *kind = FUZZ_GET_ATTR_STR(pool, "kind");
if (!(kind && kind[0] && std::string(kind) == "ObjectPool<WtUInt32>")) { FUZZ_BAIL(); }
// All objects previously created by this pool must have been destroyed before pool deletion
int live = FUZZ_GET_ATTR_INT(pool, "live_count");
if (live != 0) { FUZZ_BAIL(); }
// Safe to delete the pool now
ObjectPool<WtUInt32> *pp = static_cast<ObjectPool<WtUInt32>*>(pool);
delete pp;
// Validation: pool deleted only when no live objects remain; nothing is returned

// Validate pool handle
const char *kind = FUZZ_GET_ATTR_STR(pool, "kind");
if (!(kind && kind[0] && std::string(kind) == "ObjectPool<WtUInt32>")) { FUZZ_BAIL(); }
ObjectPool<WtUInt32> *pp = static_cast<ObjectPool<WtUInt32>*>(pool);
// Allocate and default-construct a WtUInt32 from the pool
WtUInt32 *obj = pp->construct();
// Handle allocation failure as per API contract
if (!obj) { FUZZ_BAIL(); }
// Track object-to-pool association and liveness to enforce correct destroy semantics later
FUZZ_SET_ATTR_PTR(obj, "pool", pool);
FUZZ_SET_ATTR_INT(obj, "alive", 1);
// Increment the pool's live allocation count
int live = FUZZ_GET_ATTR_INT(pool, "live_count");
FUZZ_SET_ATTR_INT(pool, "live_count", live + 1);
// Validation: non-null obj returned on success; pool is kept as an output for continued use

// Validate pool handle type
const char *kind = FUZZ_GET_ATTR_STR(pool, "kind");
if (!(kind && kind[0] && std::string(kind) == "ObjectPool<WtUInt32>")) { FUZZ_BAIL(); }
ObjectPool<WtUInt32> *pp = static_cast<ObjectPool<WtUInt32>*>(pool);
// Validate that obj is live and was allocated by this exact pool instance
void *obj_pool = FUZZ_GET_ATTR_PTR(obj, "pool");
int alive = FUZZ_GET_ATTR_INT(obj, "alive");
if (obj_pool != pool || alive != 1) { FUZZ_BAIL(); }
// Destroy the object and return memory to the pool
pp->destroy(obj);
// Mark object as not alive to prevent double free (we cannot return it as output)
