// Generate source data. Use c_str() to ensure null-termination for len==0 mode.
std::string src = FUZZ_PARAM_STR();
const char *src_c = src.c_str();

// Choose copy mode and length while enforcing API constraints and small allocations.
// - If len==0: copy strlen(src) bytes, requires src be a C-string.
// - If len>0: copy exactly len bytes (raw), requires src has at least len bytes.
const size_t kMaxCopy = 1024; // keep allocations small and bounded
size_t len_param = 0;
size_t expected_len = 0;

// Randomly decide mode, but cap work to kMaxCopy. If strlen would exceed cap, switch to len>0 mode.
unsigned int mode_pick = *FUZZ_PARAM(unsigned int) % 2;
if (mode_pick == 0) {
    // len==0 path: compute strlen(src)
    size_t slen = strlen(src_c);
    if (slen > kMaxCopy) {
        // Switch to bounded len>0 to stay within budget
        expected_len = kMaxCopy;
        len_param = expected_len; // force raw copy of bounded size
    } else {
        expected_len = slen;
        len_param = 0; // request wt_strcpy to compute length via strlen
    }
} else {
    // len>0 path: choose a raw length within available bytes and cap
    size_t max_raw = src.size();
    size_t upper = (max_raw < kMaxCopy ? max_raw : kMaxCopy);
    // upper may be 0 if src is empty; copying 0 is valid and should just write terminator
    expected_len = (upper == 0) ? 0 : (*FUZZ_PARAM(unsigned int) % (upper + 1));
    if (expected_len > upper) expected_len = upper; // safety, though modulo ensures it
    len_param = expected_len;
}

// Allocate destination with exact required capacity (len+1 or strlen+1). Ensure writable buffer.
std::vector<char> dest(expected_len + 1, '\xCD'); // prefill with sentinel

// Call target function under test.
size_t ret = wt_strcpy(dest.data(), src_c, len_param);

// Validate fundamental properties:
// - Return value equals number of bytes copied (expected_len)
// - A single NUL terminator is written at dest[expected_len]
FUZZ_ASSERT(ret == expected_len, "wt_strcpy: return value must equal expected length");
FUZZ_ASSERT(dest[expected_len] == '\0', "wt_strcpy: missing NUL terminator at expected index");

// Validate content bytes for the copied range match the chosen semantics.
for (size_t i = 0; i < expected_len; ++i) {
    // For len==0, expected_len==strlen(src_c), so src_c[i] is valid; for len>0 we copy raw bytes from src.data()
    char expected_ch = (len_param == 0) ? src_c[i] : src.data()[i];
    if (dest[i] != expected_ch) { FUZZ_BAIL(); }
}

