import json
import random
import string
from typing import Any, Dict, List

# This generator produces valid JSON or YAML configuration documents intended for WTSCfgLoader::load_from_file.
# The fuzzer stub uses FUZZ_PARAM_FILENAME to point to a file containing our bytes; the loader then parses JSON (default) or YAML.
# Strategy:
# - Prefer JSON (broad compatibility); occasionally emit YAML to exercise the YAML path.
# - Generate objects and arrays with diverse scalar types (strings, ints, uint-like, int64-range, floats, booleans),
#   including edge-case numeric magnitudes and textual booleans ("true", "yes") that map to asBoolean() in WTSVariant.
# - Include nested structures to exercise object/array append paths and memberNames/size traversals.
# - Keep size <= 4096 bytes.

_MAX_BYTES = 4096

_EDGE_INT32 = [0, 1, -1, 2**31 - 1, -2**31]
_EDGE_UINT32 = [0, 1, 2, 2**32 - 1]
_EDGE_INT64 = [0, 1, -1, 2**63 - 1, -2**63]
_EDGE_UINT64 = [0, 1, 2**64 - 1]
_EDGE_FLOATS = [0.0, -0.0, 1.0, -1.0, 1e-10, -1e-10, 1e10, -1e10, float('inf'), float('-inf')]
_BOOL_STRINGS = ["true", "True", "TRUE", "yes", "Yes", "YES", "false", "no"]

def _rand_str(rng: random.Random, min_len: int = 0, max_len: int = 20) -> str:
    length = rng.randint(min_len, max_len)
    # Favor ASCII but include some UTF-8 edge cases
    choices = string.ascii_letters + string.digits + "_-./:@#"
    s = ''.join(rng.choice(choices) for _ in range(length))
    # Occasionally return empty or a special key
    if length == 0:
        return ""
    return s

def _rand_key(rng: random.Random) -> str:
    specials = [
        "id", "name", "path", "source", "enabled", "count", "rate", "threshold",
        "timestamp", "flags", "items", "data", "config", "nested", "list", "object",
        "value", "u32", "i32", "u64", "i64", "real", "bool", "string"
    ]
    if rng.random() < 0.6:
        return rng.choice(specials)
    return _rand_str(rng, 1, 16)

def _rand_number(rng: random.Random) -> Any:
    kind = rng.random()
    if kind < 0.33:
        return rng.choice(_EDGE_INT32 + _EDGE_INT64)
    elif kind < 0.66:
        return rng.choice(_EDGE_UINT32 + _EDGE_UINT64)
    else:
        # Replace infs with large finite values for JSON compatibility later
        v = rng.choice(_EDGE_FLOATS)
        if v == float('inf'):
            return 1e308
        if v == float('-inf'):
            return -1e308
        return v

def _rand_bool_or_boolstring(rng: random.Random) -> Any:
    if rng.random() < 0.5:
        return rng.choice([True, False])
    else:
        return rng.choice(_BOOL_STRINGS)

def _rand_scalar(rng: random.Random) -> Any:
    t = rng.random()
    if t < 0.25:
        return _rand_number(rng)
    elif t < 0.5:
        return _rand_bool_or_boolstring(rng)
    elif t < 0.75:
        # string possibly representing a number to exercise string->number conversions
        if rng.random() < 0.5:
            return str(_rand_number(rng))
        # general string
        return _rand_str(rng, 0, 24)
    else:
        # decimal-like string
        return f"{rng.randint(-100000,100000)}.{rng.randint(0,999999)}"

def _make_array(rng: random.Random, depth: int) -> List[Any]:
    n = rng.randint(0, 8)
    arr: List[Any] = []
    for _ in range(n):
        arr.append(_make_value(rng, depth + 1))
    return arr

def _make_object(rng: random.Random, depth: int) -> Dict[str, Any]:
    m = rng.randint(1, 8)
    obj: Dict[str, Any] = {}
    # Seed with some known keys to drive diverse accessors
    seeds = [
        ("i32", rng.choice(_EDGE_INT32)),
        ("u32", int(rng.choice(_EDGE_UINT32))),
        ("i64", rng.choice(_EDGE_INT64)),
        ("u64", int(rng.choice(_EDGE_UINT64))),
        ("real", float(rng.choice([0.0, 1.2345, -98765.4321, 3.1415926535]))),
        ("bool", rng.choice([True, False])),
        ("yes", "yes"),
        ("true", "true"),
        ("name", _rand_str(rng, 3, 12)),
    ]
    rng.shuffle(seeds)
    for k, v in seeds[:rng.randint(3, len(seeds))]:
        obj[k] = v
    # Add random entries
    for _ in range(m):
        key = _rand_key(rng)
        obj[key] = _make_value(rng, depth + 1)
    return obj

def _make_value(rng: random.Random, depth: int = 0) -> Any:
    # Limit depth to avoid huge documents
    if depth > 3:
        return _rand_scalar(rng)
    p = rng.random()
    if p < 0.5:
        return _rand_scalar(rng)
    elif p < 0.75:
        return _make_array(rng, depth)
    else:
        return _make_object(rng, depth)

def _make_root(rng: random.Random) -> Any:
    # Root as object to align with typical config shape
    root = _make_object(rng, 0)
    # Add an "items" array of objects for variety
    items = []
    for i in range(rng.randint(0, 5)):
        item = {
            "id": rng.randint(0, 1_000_000),
            "enabled": rng.choice([True, False, "true", "yes", "no", "false"]),
            "threshold": float(rng.randint(-1000, 1000)) / (rng.randint(1, 100) or 1),
            "tags": [_rand_str(rng, 0, 10) for _ in range(rng.randint(0, 5))],
        }
        # occasionally nested object
        if rng.random() < 0.6:
            item["nested"] = _make_object(rng, 2)
        items.append(item)
    root["items"] = items
    return root

def _to_json_bytes(obj: Any, ensure_utf8: bool = True) -> bytes:
    # Use separators to keep size compact
    s = json.dumps(obj, ensure_ascii=ensure_utf8, separators=(",", ":"))
    # Ensure trailing newline for file friendliness
    data = (s + "\n").encode("utf-8")
    if len(data) > _MAX_BYTES:
        # As a fallback, truncate large substructures and re-serialize
        # Keep this conservative to maintain validity
        if isinstance(obj, dict):
            trimmed = {}
            for i, (k, v) in enumerate(obj.items()):
                trimmed[k] = v
                if i > 10:
                    break
            s = json.dumps(trimmed, ensure_ascii=ensure_utf8, separators=(",", ":"))
            data = (s + "\n").encode("utf-8")
        else:
            data = data[:_MAX_BYTES]
    return data

def _to_yaml_bytes(obj: Any) -> bytes:
    # Minimal YAML emitter sufficient for scalars/arrays/objects used here.
    # Indentation-based, handles strings, numbers, booleans, and nested structures.
    def emit(val: Any, indent: int, out: List[str]):
        ind = "  " * indent
        if isinstance(val, dict):
            if not val:
                out.append("{}")
                return
            for i, (k, v) in enumerate(val.items()):
                safe_k = str(k)
                if isinstance(v, (dict, list)):
                    out.append(f"{ind}{safe_k}:")
                    emit(v, indent + 1, out)
                else:
                    out.append(f"{ind}{safe_k}: {format_scalar(v)}")
        elif isinstance(val, list):
            if not val:
                out.append("[]")
                return
            for item in val:
                if isinstance(item, (dict, list)):
                    out.append(f"{ind}-")
                    emit(item, indent + 1, out)
                else:
                    out.append(f"{ind}- {format_scalar(item)}")
        else:
            out.append(ind + format_scalar(val))

    def needs_quotes(s: str) -> bool:
        if s == "" or s.strip() != s:
            return True
        # Reserve special YAML tokens
        specials = {"null", "true", "false", "yes", "no", "on", "off"}
        if s.lower() in specials:
            return True
        # Contains YAML syntax chars
        if any(c in s for c in [":", "#", "-", "{", "}", "[", "]", ",", "&", "*", "?", "|", ">", "%", "@", "\n"]):
            return True
        return False

    def format_scalar(v: Any) -> str:
        if isinstance(v, bool):
            return "true" if v else "false"
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            # Avoid NaN/inf in YAML by clamping
            if isinstance(v, float):
                if v != v:
                    return "0.0"
                if v == float('inf'):
                    return "1.0e308"
                if v == float('-inf'):
                    return "-1.0e308"
            return str(v)
        s = str(v)
        if needs_quotes(s):
            # Use double quotes and escape
            escaped = s.replace('\\', '\\\\').replace('"', '\\"').replace("\n", "\\n")
            return f'"{escaped}"'
        return s

    lines: List[str] = []
    emit(obj, 0, lines)
    data = ("\n".join(lines) + "\n").encode("utf-8")
    if len(data) > _MAX_BYTES:
        # Fallback to JSON which is typically more compact
        return _to_json_bytes(obj)
    return data

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    root = _make_root(rng)
    # Decide format: mostly JSON, sometimes YAML
    use_yaml = rng.random() < 0.25
    data = _to_yaml_bytes(root) if use_yaml else _to_json_bytes(root)
    # Final guard on size
    if len(data) > _MAX_BYTES:
        data = data[:_MAX_BYTES]
    return data

import json
import random
import string
from typing import Any, List, Dict, Tuple

# This generator produces valid serialized configuration text for WTSCfgLoader::load_from_content.
# The fuzzer stub chooses JSON when isYaml == false, and YAML when isYaml == true. We cannot
# control the flag directly, but we can emit content that is valid for BOTH JSON and YAML so that
# either path is likely to parse successfully. YAML 1.2 is a superset of JSON, so valid JSON
# should also parse as YAML in typical loaders. Therefore, we primarily emit JSON.
#
# Strategy:
# - Construct diverse, valid JSON documents exercising numbers (int/float), strings, booleans,
#   null, arrays, nested objects, and edge-case string content (escapes, unicode, long keys).
# - Vary structure and depth within safe limits to avoid overly large documents.
# - Keep total size under 4096 bytes.
# - Ensure deterministic randomness via provided seed.
#
# Notes on WTSVariant usage:
# - WTSVariant stores scalars as strings internally and converts via atof/strtoll/etc.
#   We include values that exercise integer ranges, floating point formats, boolean text, and
#   strings that look like numbers to exercise conversions.
# - Include keys that typical configs might use (ids, name, enabled, list, map, nested), and also
#   uncommon keys to broaden paths.


def _rand_ascii(r: random.Random, min_len: int, max_len: int) -> str:
    length = r.randint(min_len, max_len)
    alphabet = string.ascii_letters + string.digits + " _-./:@#"
    return "".join(r.choice(alphabet) for _ in range(length))


def _rand_unicode_str(r: random.Random, min_len: int, max_len: int) -> str:
    length = r.randint(min_len, max_len)
    # Mix of ASCII and some BMP unicode code points
    pieces: List[str] = []
    for _ in range(length):
        t = r.random()
        if t < 0.7:
            pieces.append(r.choice(string.ascii_letters + string.digits))
        elif t < 0.85:
            pieces.append(r.choice([" ", "-", "_", "/", ".", ",", ":"]))
        elif t < 0.95:
            # common non-ASCII
            pieces.append(chr(r.choice([
                0x00E9, 0x00F1, 0x00FC, 0x03B1, 0x03C0, 0x0416, 0x4E2D, 0x56FD, 0x65E5, 0x672C
            ])))
        else:
            # random BMP excluding surrogates
            while True:
                cp = r.randint(0x20, 0xFFFD)
                if not (0xD800 <= cp <= 0xDFFF):
                    pieces.append(chr(cp))
                    break
    return "".join(pieces)


def _interesting_numbers(r: random.Random) -> List[Any]:
    nums: List[Any] = []
    # Integers around 32-bit and 64-bit boundaries
    ints = [
        0, 1, -1,
        2**31 - 1, -2**31,
        2**32 - 1,
        2**63 - 1, -2**63,
        r.randint(-10**9, 10**9),
        r.randint(0, 2**32 - 1)
    ]
    nums.extend(ints)
    # Floats with various formats
    floats = [
        0.0, -0.0, 1.0, -1.0, 3.1415926535, -2.718281828,
        1e10, 1e-10, -9.22e18, 6.022e23,
        float(r.randrange(-100000, 100000)) / (10 ** r.randint(0, 6))
    ]
    nums.extend(floats)
    return nums


def _interesting_strings(r: random.Random) -> List[str]:
    return [
        "", "true", "false", "yes", "no", "null", "NaN", "Infinity", "-Infinity",
        "00123", "+42", "-007", "3.1415", "6.02e23", "0xFF", "0755",
        _rand_ascii(r, 3, 12),
        _rand_unicode_str(r, 3, 12),
        "line1\nline2\tTabbed\\Backslash\"Quote",
    ]


def _make_array(r: random.Random, depth: int) -> List[Any]:
    length = r.randint(0, 8)
    arr: List[Any] = []
    for _ in range(length):
        arr.append(_make_value(r, depth + 1))
    return arr


def _make_object(r: random.Random, depth: int) -> Dict[str, Any]:
    obj: Dict[str, Any] = {}
    # Core keys common in configs
    core_keys = [
        "id", "name", "version", "enabled", "threshold", "timeout_ms",
        "ratio", "path", "created_at", "tags", "limits", "nested", "list",
        "map", "description", "debug", "pi", "max_u32", "max_u64"
    ]
