        obj[key] = _make_value(r, depth + 1)

    return obj


def _make_typed_value_for_key(r: random.Random, key: str, depth: int) -> Any:
    if key in ("enabled", "debug"):
        return r.choice([True, False])
    if key in ("id", "timeout_ms"):
        return r.randint(0, 2**31 - 1)
    if key == "version":
        # Semantic-looking string to exercise string-to-number behavior too
        return f"{r.randint(0,9)}.{r.randint(0,9)}.{r.randint(0,99)}"
    if key == "name":
        return _rand_unicode_str(r, 5, 20)
    if key == "path":
        return "/" + "/".join(_rand_ascii(r, 1, 6) for _ in range(r.randint(1, 4)))
    if key == "ratio":
        return round(r.uniform(0.0, 1.0), 6)
    if key == "threshold":
        return r.choice(_interesting_numbers(r))
    if key == "created_at":
        # ISO-like timestamp string
        return f"202{r.randint(0,9)}-{r.randint(1,12):02d}-{r.randint(1,28):02d}T{r.randint(0,23):02d}:{r.randint(0,59):02d}:{r.randint(0,59):02d}Z"
    if key == "tags":
        return [_rand_ascii(r, 3, 10) for _ in range(r.randint(0, 6))]
    if key == "limits":
        return {"min": r.randint(-1000, 0), "max": r.randint(0, 1000)}
    if key == "nested":
