        return r.choice([2**64 - 1, str(2**64 - 1)])
    return _make_value(r, depth + 1)


def _make_value(r: random.Random, depth: int) -> Any:
    # Limit depth to avoid excessive nesting/size
    if depth > 4:
        return r.choice([None, True, False, r.randint(-100, 100), r.uniform(-100.0, 100.0), _rand_ascii(r, 1, 8)])

    choice = r.random()
    if choice < 0.25:
        return _make_object(r, depth)
    elif choice < 0.5:
        return _make_array(r, depth)
    elif choice < 0.7:
        return r.choice(_interesting_numbers(r))
    elif choice < 0.9:
        return r.choice(_interesting_strings(r))
    else:
        return r.choice([True, False, None])


def _ensure_size_limit(doc: str, r: random.Random, limit: int = 4096) -> str:
    if len(doc) <= limit:
        return doc
    # If exceeded, regenerate a smaller object with stricter bounds
    # Reduce arrays/objects sizes by reseeding a constrained build
    def small_object() -> Dict[str, Any]:
        obj: Dict[str, Any] = {}
        for k in ["id", "name", "enabled", "ratio", "tags", "limits"]:
            obj[k] = _make_typed_value_for_key(r, k, 1)
        return obj

    small_doc = json.dumps(small_object(), ensure_ascii=False, separators=(",", ":"))
    if len(small_doc) <= limit:
        return small_doc
    # As a last resort, emit a tiny valid JSON
    return json.dumps({"id": 1, "name": "a", "enabled": True})


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Randomly decide top-level container type with a bias toward object-based configs
    top_type = r.choices(["object", "array", "scalar"], weights=[60, 30, 10])[0]
    if top_type == "object":
        data = _make_object(r, 0)
        # Add some numeric-looking strings to exercise string conversions
        if r.random() < 0.7:
            data["as_string_number"] = r.choice(["12345", "-67890", "1.234e5", "0007"]) 
        if r.random() < 0.5:
            data["boolean_text"] = r.choice(["true", "false", "yes", "no"])
    elif top_type == "array":
        # Mix various elements
        data = []  # type: List[Any]
        for _ in range(r.randint(3, 10)):
            data.append(_make_value(r, 0))
    else:
        # Scalar root (valid JSON and YAML)
        data = r.choice([
            r.randint(-1000, 1000),
            round(r.uniform(-1000.0, 1000.0), 6),
            True, False, None,
            _rand_unicode_str(r, 3, 24)
        ])

    # Serialize as compact JSON (valid YAML 1.2 as well)
    doc = json.dumps(data, ensure_ascii=False, separators=(",", ":"))
    doc = _ensure_size_limit(doc, r, 4096)

    # Return as bytes (UTF-8)
    return doc.encode("utf-8")

import random
import json
from typing import List, Tuple

# This generator produces valid configuration texts for WTSCfgLoader::load_from_content.
# The fuzzer toggles isYaml randomly, so our single byte stream must be a valid config
# for both JSON (when isYaml==false) and YAML (when isYaml==true).
# Strategy:
# - Emit a variety of documents, each valid YAML.
# - Many emitted forms are also valid JSON (pure JSON is valid YAML 1.2), ensuring coverage
#   regardless of format flag.
# - Include documents exercising numbers, strings, booleans, arrays, maps, nesting, and
#   different scalar representations (quoted/unquoted), while staying valid.
# - Keep under 4096 bytes.

_JSON_SAFE_STRINGS = [
    "alpha",
    "beta",
    "gamma",
    "delta",
    "true",   # quoted later when needed to avoid YAML boolean ambiguity
    "false",
    "yes",
    "no",
    "null",
    "NA",
    "2024-12-31",
    "10:20:30",
    "1e3",
    "leading and trailing spaces",
    "unicode πş",
]

_NUMBERS = [0, 1, -1, 42, 2147483647, -2147483648, 4294967295, 9007199254740991, -9007199254740991]
_FLOATS = [0.0, -0.0, 1.5, -2.75, 3.1415926535, 1e10, -2.5e-5]

# Some YAML-only niceties that remain JSON-compatible when rendered as JSON literals or YAML scalars
_BOOL_PAIRS = [(True, False), (False, True)]

MAX_LEN = 4096


def _rand_str(rng: random.Random) -> str:
    s = rng.choice(_JSON_SAFE_STRINGS)
    # randomly add escapable characters but keep JSON-safe when quoted
    if rng.random() < 0.3:
        s += rng.choice(["_", "-", ":", ",", ".", "/"]) + str(rng.randint(0, 999))
    return s


def _yaml_quote(s: str) -> str:
    # Use double quotes and escape common characters to be safe across YAML/JSON-like parsers
    esc = s.replace("\\", "\\\\").replace("\"", "\\\"")
    return f'"{esc}"'


def _json_value(rng: random.Random, depth: int) -> object:
    # produce JSON-compatible value (also valid YAML)
    if depth <= 0:
        choice = rng.randint(0, 4)
    else:
        choice = rng.randint(0, 6)

    if choice == 0:
        return rng.choice(_NUMBERS)
    if choice == 1:
        return rng.choice(_FLOATS)
    if choice == 2:
        return rng.choice([True, False])
    if choice == 3:
        return None
    if choice == 4:
        return _rand_str(rng)
    if choice == 5:
        # array
        n = rng.randint(0, 6)
        return [_json_value(rng, depth - 1) for _ in range(n)]
    # object
    n = rng.randint(0, 6)
    obj = {}
    for _ in range(n):
        key = _rand_str(rng)
        obj[key] = _json_value(rng, depth - 1)
    return obj


def _render_yaml_from_json_compatible(val, indent: int = 0) -> str:
    # Render a JSON-compatible value as YAML using block style where useful.
    sp = " " * indent
    if isinstance(val, dict):
        if not val:
            return "{}"
        lines = []
        for k, v in val.items():
            # quote keys that might be ambiguous
            key = _yaml_quote(str(k)) if not str(k).isidentifier() else k
            child = _render_yaml_from_json_compatible(v, indent + 2)
            if "\n" in child:
                lines.append(f"{sp}{key}:\n{child}")
            else:
                lines.append(f"{sp}{key}: {child}")
        return "\n".join(lines)
    if isinstance(val, list):
        if not val:
            return "[]"
        lines = []
        for item in val:
            child = _render_yaml_from_json_compatible(item, indent + 2)
            if "\n" in child:
                lines.append(f"{sp}-\n{child}")
            else:
                lines.append(f"{sp}- {child}")
        return "\n".join(lines)
    if isinstance(val, str):
        # quote to avoid YAML tag resolution surprises
        return _yaml_quote(val)
    if isinstance(val, bool):
        return "true" if val else "false"
    if val is None:
        return "null"
    # numbers
    return str(val)


def _make_yaml_doc(rng: random.Random) -> str:
    # Build a YAML document exercising mappings, sequences, and scalars.
    root = {
        "name": _rand_str(rng),
        "version": rng.choice([1, 2, 3]),
        "enabled": rng.choice([True, False]),
        "threshold": rng.choice(_FLOATS),
        "limits": {
            "min": rng.choice(_NUMBERS),
            "max": rng.choice(_NUMBERS),
        },
        "tags": [_rand_str(rng) for _ in range(rng.randint(0, 5))],
        "servers": [
            {
                "host": _rand_str(rng),
                "port": rng.randint(1, 65535),
                "ssl": rng.choice([True, False]),
            }
            for _ in range(rng.randint(0, 4))
        ],
        "matrix": [
            [rng.randint(-5, 5) for _ in range(rng.randint(0, 4))]
            for _ in range(rng.randint(0, 4))
        ],
        "misc": _json_value(rng, depth=2),
    }
    return _render_yaml_from_json_compatible(root)


def _make_json_doc(rng: random.Random) -> str:
    # Pure JSON document (valid YAML as well)
    doc = {
        "title": _rand_str(rng),
        "id": rng.randint(0, 2**63 - 1),
        "active": rng.choice([True, False]),
        "ratio": rng.choice(_FLOATS),
        "items": [_json_value(rng, 2) for _ in range(rng.randint(0, 6))],
        "config": _json_value(rng, 3),
    }
    return json.dumps(doc, ensure_ascii=False, separators=(",", ":"))


def _make_yaml_seq_doc(rng: random.Random) -> str:
    # A YAML sequence at root; also a valid JSON array
    arr = [_json_value(rng, 2) for _ in range(rng.randint(1, 6))]
    # Render in YAML block sequence style
    body = _render_yaml_from_json_compatible(arr)
    return body


def _make_minimal_docs(rng: random.Random) -> List[str]:
    # Tiny but valid docs that exercise scalar parsing
    scalars = [
        "null",  # null
        "true",
        "false",
        "0",
        "-1",
        "3.14159",
        _yaml_quote("simple"),
        _yaml_quote("yes"),  # quoted to force string, not boolean
    ]
    rng.shuffle(scalars)
    return scalars[: rng.randint(1, min(4, len(scalars)))]


def _maybe_add_directives(rng: random.Random, doc: str) -> str:
    # Optionally add YAML version/tag directives; still valid YAML, ignored by JSON parser if not used.
    # To remain valid JSON when parsed as JSON, we avoid directives if we intend JSON. We only add
    # when the content itself stays valid YAML and JSON parsers won't be used. But since the fuzzer
    # decides format, keep directives disabled by default to maintain dual validity.
    return doc


def _join_documents(rng: random.Random, docs: List[str]) -> str:
    # Optionally create a multi-document YAML stream with --- separators.
    # Note: JSON does not support multi-doc; to remain valid in both modes, emit single document
    # most of the time. Occasionally, we still emit multi-doc YAML; it will be invalid JSON but
    # still valid YAML. Since the fuzzer sometimes sets isYaml=true, these inputs will exercise
    # that path. To keep general validity, we bias towards single-doc.
    if len(docs) == 1:
        return docs[0]
    return "\n---\n".join(docs)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a template
    kind = rng.random()
    candidates: List[str] = []

    if kind < 0.35:
        candidates.append(_make_json_doc(rng))
    elif kind < 0.7:
        candidates.append(_make_yaml_doc(rng))
    else:
        candidates.append(_make_yaml_seq_doc(rng))

    # Maybe append minimal scalar documents to exercise YAML multi-doc streams.
    # Keep the probability low to maintain cross-format validity.
    if kind >= 0.55 and rng.random() < 0.3:
        candidates.extend(_make_minimal_docs(rng))

    content = _join_documents(rng, candidates)
    content = _maybe_add_directives(rng, content)

    # Ensure UTF-8 bytes and size limit
    data = content.encode("utf-8")
    if len(data) > MAX_LEN:
        data = data[:MAX_LEN]
    return data
